/* ═══════ 第二层：样式引用变量 ═══════ */

.egg-cb-wrapper{display:block;margin:8px auto;max-width:100%;font-family:'M PLUS Rounded 1c',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,'Helvetica Neue','Noto Sans SC','PingFang SC','Microsoft YaHei',sans-serif}

.egg-cb-details{background:var(--cb-bg);border:2px solid var(--cb-border);border-radius:16px;overflow:hidden;box-shadow:0 3px 12px var(--cb-shadow-base),inset 0 1px 0 var(--cb-inset);transition:box-shadow .35s ease,transform .35s cubic-bezier(.34,1.3,.64,1);position:relative}
