.egg-cb-summary{display:flex;justify-content:space-between;align-items:center;padding:7px 16px;background:linear-gradient(90deg,var(--cb-header-from) 0%,var(--cb-header-mid) 45%,var(--cb-header-to) 100%);border-bottom:2.5px dashed var(--cb-dash);cursor:pointer;user-select:none;list-style:none;position:relative;z-index:2;transition:background .3s ease,filter .3s ease,border-color .3s ease;color:var(--cb-title-color);font-weight:700;font-size:.95em;text-shadow:0 1px 2px var(--cb-title-shadow)}
.egg-cb-summary::-webkit-details-marker,.egg-cb-summary::marker{display:none;content:''}
.egg-cb-summary::after{content:none!important;display:none!important}
.egg-cb-summary:hover{background:linear-gradient(90deg,var(--cb-header-hover-from) 0%,var(--cb-header-hover-mid) 45%,var(--cb-header-hover-to) 100%);filter:brightness(1.04)}
.egg-cb-details[open]>.egg-cb-summary{border-bottom-color:var(--cb-dash-open)}

.egg-cb-title-content{display:flex;align-items:center;gap:8px;flex:1;min-width:0}

.egg-cb-remy{display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;font-size:22px;line-height:1;filter:drop-shadow(0 2px 4px var(--cb-emoji-glow));flex-shrink:0}
.egg-cb-toast{display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;font-size:22px;line-height:1;filter:drop-shadow(0 2px 4px var(--cb-emoji-glow));flex-shrink:0}

.egg-cb-title-text{word-break:break-word;overflow:hidden;text-overflow:ellipsis}

/* ── 日间动画 ── */
.egg-cb-remy.anim-day{animation:eggRemyWiggle 2.8s ease-in-out infinite}
.egg-cb-toast.anim-day{animation:eggToastBounce 3.2s ease-in-out infinite}

@keyframes eggRemyWiggle{0%,100%{transform:translateX(0) translateY(0) rotate(0deg)}8%{transform:translateX(-2px) translateY(-1px) rotate(-6deg)}16%{transform:translateX(0) translateY(-3px) rotate(0deg)}24%{transform:translateX(2px) translateY(-1px) rotate(6deg)}32%{transform:translateX(0) translateY(0) rotate(0deg)}40%{transform:translateX(-1px) translateY(-1px) rotate(-10deg)}48%{transform:translateX(0) translateY(-4px) rotate(2deg)}55%{transform:translateX(1px) translateY(0) rotate(4deg)}65%{transform:translateX(-1px) translateY(-1px) rotate(-3deg)}75%{transform:translateX(0) translateY(0) rotate(0deg)}85%{transform:translateX(0) translateY(-1px) rotate(-2deg)}95%{transform:translateX(0) translateY(0) rotate(1deg)}}

@keyframes eggToastBounce{0%{transform:translateY(0) rotate(0deg) scale(1,1)}5%{transform:translateY(1px) rotate(0deg) scale(1.02,0.97)}14%{transform:translateY(-8px) rotate(4deg) scale(0.96,1.06)}18%{transform:translateY(-8px) rotate(3deg) scale(0.97,1.04)}26%{transform:translateY(0) rotate(0deg) scale(1.08,0.92)}29%{transform:translateY(1px) rotate(-1deg) scale(1.1,0.88)}36%{transform:translateY(-4px) rotate(-2deg) scale(0.98,1.03)}42%{transform:translateY(0) rotate(0deg) scale(1.04,0.95)}44%{transform:translateY(0) rotate(0deg) scale(1.05,0.94)}48%{transform:translateY(-1.5px) rotate(0deg) scale(0.99,1.01)}52%,100%{transform:translateY(0) rotate(0deg) scale(1,1)}}

/* ── 夜间动画 ── */
.egg-cb-remy.anim-night{animation:eggRemySway 3.5s ease-in-out infinite}
.egg-cb-toast.anim-night{animation:eggStarPulse 2.6s ease-in-out infinite}

@keyframes eggRemySway{
    0%,100%{transform:rotate(0deg) translateY(0)}
    15%{transform:rotate(-5deg) translateY(-1px)}
    30%{transform:rotate(3deg) translateY(0)}
    50%{transform:rotate(-3deg) translateY(-2px)}
    70%{transform:rotate(4deg) translateY(0)}
    85%{transform:rotate(-2deg) translateY(-1px)}
}

@keyframes eggStarPulse{
