@keyframes eggContentIn{0%{opacity:0;transform:translateY(-6px) scaleY(.96);clip-path:inset(0 0 100% 0)}100%{opacity:1;transform:translateY(0) scaleY(1);clip-path:inset(0 0 0 0)}}

