.egg-cb-content em{font-style:italic;opacity:.9;color:var(--cb-em)}
.egg-cb-content code{background:var(--cb-code-bg);color:var(--cb-code-text);padding:2px 6px;border-radius:4px;font-size:.85em;font-family:'Consolas','Monaco',monospace;border:1px solid var(--cb-code-border)}
