    --stat-scrollbar-track-to:rgba(27,94,32,.12);
    --stat-scrollbar-thumb-from:rgba(76,175,80,.4);
    --stat-scrollbar-thumb-mid:rgba(76,175,80,.6);
    --stat-scrollbar-thumb-to:rgba(27,94,32,.7);
    --stat-scrollbar-thumb-hover-from:rgba(76,175,80,.6);
    --stat-scrollbar-thumb-hover-mid:rgba(27,94,32,.8);
    --stat-scrollbar-thumb-hover-to:rgba(27,94,32,.9);
    --stat-scrollbar-thumb-inset:rgba(255,255,255,.12);

    --stat-emoji-glow:rgba(76,175,80,.4);
}

/* ═══════ 第二层：样式引用变量 ═══════ */

.egg-status-wrapper{display:block;margin:20px auto;max-width:100%;font-family:'M PLUS Rounded 1c',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,'Helvetica Neue','Noto Sans SC','PingFang SC','Microsoft YaHei',sans-serif}

.egg-status-details{background:var(--stat-bg);border:2px solid var(--stat-border);border-radius:16px;overflow:hidden;box-shadow:0 3px 12px var(--stat-shadow-base),inset 0 1px 0 var(--stat-inset);transition:box-shadow .35s ease,transform .35s cubic-bezier(.34,1.3,.64,1);position:relative}
.egg-status-details:hover{transform:translateY(-3px);box-shadow:0 8px 24px -4px var(--stat-shadow-hover),inset 0 1px 0 var(--stat-inset)}
.egg-status-details[open]{box-shadow:0 5px 18px var(--stat-shadow-open),inset 0 1px 0 var(--stat-inset)}
.egg-status-details[open]:hover{transform:translateY(-3px);box-shadow:0 10px 30px -4px var(--stat-shadow-open-hover),inset 0 1px 0 var(--stat-inset)}

.egg-status-summary{display:flex;justify-content:space-between;align-items:center;padding:7px 16px;background:linear-gradient(90deg,var(--stat-header-from) 0%,var(--stat-header-mid) 45%,var(--stat-header-to) 100%);border-bottom:2.5px dashed var(--stat-dash);cursor:pointer;user-select:none;list-style:none;position:relative;z-index:2;transition:background .3s ease,filter .3s ease,border-color .3s ease;color:var(--stat-title-color);font-weight:700;font-size:.95em;text-shadow:0 1px 2px var(--stat-title-shadow)}
.egg-status-summary::-webkit-details-marker,.egg-status-summary::marker{display:none;content:''}
.egg-status-summary::after{content:none!important;display:none!important}
.egg-status-summary:hover{background:linear-gradient(90deg,var(--stat-header-hover-from) 0%,var(--stat-header-hover-mid) 45%,var(--stat-header-hover-to) 100%);filter:brightness(1.04)}
.egg-status-details[open]>.egg-status-summary{border-bottom-color:var(--stat-dash-open)}

.egg-status-title-content{display:flex;align-items:center;gap:8px;flex:1;min-width:0}

.egg-status-icon{display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;font-size:22px;line-height:1;filter:drop-shadow(0 2px 4px var(--stat-emoji-glow));flex-shrink:0}
.egg-status-title-text{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.egg-status-deco{display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;font-size:22px;line-height:1;filter:drop-shadow(0 2px 4px var(--stat-emoji-glow));flex-shrink:0}

/* ── 日间动画 ── */
.egg-status-icon.anim-day{animation:eggStatusPulse 2.5s ease-in-out infinite}
.egg-status-deco.anim-day{animation:eggDecoFloat 3s ease-in-out infinite}

@keyframes eggStatusPulse{0%,100%{transform:scale(1) rotate(0deg)}25%{transform:scale(1.1) rotate(-5deg)}50%{transform:scale(1) rotate(0deg)}75%{transform:scale(1.08) rotate(5deg)}}
@keyframes eggDecoFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}

/* ── 夜间动画 ── */
.egg-status-icon.anim-night{animation:eggStatusBreath 3.5s ease-in-out infinite}
.egg-status-deco.anim-night{animation:eggDecoSway 4s ease-in-out infinite}

@keyframes eggStatusBreath{
    0%,100%{transform:scale(1) rotate(0deg);opacity:1}
    25%{transform:scale(1.06) rotate(-3deg);opacity:.9}
    50%{transform:scale(.97) rotate(0deg);opacity:1}
    75%{transform:scale(1.04) rotate(3deg);opacity:.92}
}
@keyframes eggDecoSway{
    0%,100%{transform:translateY(0) rotate(0deg)}
    15%{transform:translateY(-2px) rotate(5deg)}
    35%{transform:translateY(-4px) rotate(-3deg)}
    55%{transform:translateY(-1px) rotate(4deg)}
    75%{transform:translateY(-3px) rotate(-5deg)}
    90%{transform:translateY(-1px) rotate(2deg)}
}

