.egg-status-content{position:relative;z-index:2;padding:14px 18px;padding-right:12px;max-height:400px;overflow-y:auto;overflow-x:hidden;background:linear-gradient(180deg,var(--stat-content-from) 0%,var(--stat-content-mid) 60%,var(--stat-content-to) 100%);color:var(--stat-text);font-size:.88em;line-height:1.75;white-space:pre-wrap;word-wrap:break-word;transform-origin:top center}
.egg-status-details[open]>.egg-status-content{animation:eggStatusIn .4s cubic-bezier(.23,1,.32,1) forwards}
@keyframes eggStatusIn{0%{opacity:0;transform:translateY(-6px) scaleY(.96);clip-path:inset(0 0 100% 0)}100%{opacity:1;transform:translateY(0) scaleY(1);clip-path:inset(0 0 0 0)}}

.egg-status-section{margin-bottom:12px;padding-bottom:10px;border-bottom:1.5px dashed var(--stat-section-dash)}
