.egg-status-content p{margin:6px 0}.egg-status-content p:first-child{margin-top:0}.egg-status-content p:last-child{margin-bottom:0}
.egg-status-content strong{font-weight:700;color:var(--stat-strong);text-shadow:0 0 6px var(--stat-strong-glow)}
.egg-status-content em{font-style:italic;opacity:.9;color:var(--stat-em)}
.egg-status-content code{background:var(--stat-code-bg);color:var(--stat-code-text);padding:2px 6px;border-radius:4px;font-size:.85em;font-family:'Consolas','Monaco',monospace;border:1px solid var(--stat-code-border)}
.egg-status-content a{color:var(--stat-link);text-decoration:none;border-bottom:2px dotted var(--stat-link-border);transition:all .2s;font-weight:600}
.egg-status-content a:hover{color:var(--stat-link-hover);border-bottom-color:var(--stat-link-border-hover)}
.egg-status-content ul,.egg-status-content ol{margin:6px 0;padding-left:20px}.egg-status-content li{margin:3px 0}.egg-status-content li::marker{color:var(--stat-marker)}
.egg-status-content blockquote{border-left:3px solid var(--stat-bq-border);background:var(--stat-bq-bg);padding:6px 10px;margin:8px 0;border-radius:0 6px 6px 0;font-style:italic;color:var(--stat-bq-text)}
