.egg-status-content::-webkit-scrollbar-thumb:hover{background:linear-gradient(180deg,var(--stat-scrollbar-thumb-hover-from) 0%,var(--stat-scrollbar-thumb-hover-mid) 50%,var(--stat-scrollbar-thumb-hover-to) 100%)}

@media(max-width:480px){.egg-status-details{border-radius:14px}.egg-status-summary{padding:6px 12px;font-size:.9em}.egg-status-content{max-height:320px;padding:10px 14px;font-size:.84em}.egg-status-icon{width:24px;height:24px;font-size:17px}.egg-status-deco{width:24px;height:24px;font-size:17px}}
